use anyhow::Result;
use regex::Regex;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use tokio::fs;
use tracing::{info, warn};

use crate::injection;
use crate::patterns::CREDENTIAL_PATTERNS;

/// Overall result of an audit run
#[derive(Debug, Serialize, Deserialize)]
pub struct AuditReport {
    pub skills_scanned: usize,
    pub findings: Vec<Finding>,
    pub hash_baseline_updated: bool,
}

/// A single security finding
#[derive(Debug, Serialize, Deserialize)]
pub struct Finding {
    pub skill: String,
    pub severity: Severity,
    pub category: FindingCategory,
    pub detail: String,
    pub file: Option<String>,
    pub line: Option<usize>,
}

#[derive(Debug, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord, Clone, Copy)]
#[serde(rename_all = "UPPERCASE")]
pub enum Severity {
    Info,
    Low,
    Medium,
    High,
    Critical,
}

impl std::fmt::Display for Severity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Severity::Info => write!(f, "INFO"),
            Severity::Low => write!(f, "LOW"),
            Severity::Medium => write!(f, "MEDIUM"),
            Severity::High => write!(f, "HIGH"),
            Severity::Critical => write!(f, "CRITICAL"),
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
pub enum FindingCategory {
    HashMismatch,
    CredentialExposure,
    InjectionPattern,
    UndeclaredPermission,
    SuspiciousContent,
}

/// Run a full audit of the skills directory
pub async fn run_audit(skills_path: &str, offline: bool) -> Result<AuditReport> {
    let path = resolve_home(skills_path);
    info!("Starting audit of {}", path.display());

    let mut findings = Vec::new();
    let mut skills_scanned = 0;

    if !path.exists() {
        warn!("Skills directory not found: {}", path.display());
        return Ok(AuditReport {
            skills_scanned: 0,
            findings,
            hash_baseline_updated: false,
        });
    }

    let mut dir = fs::read_dir(&path).await?;
    while let Some(entry) = dir.next_entry().await? {
        let skill_path = entry.path();
        if skill_path.is_dir() {
            let skill_name = skill_path
                .file_name()
                .unwrap_or_default()
                .to_string_lossy()
                .to_string();

            let skill_findings = audit_skill_dir(&skill_path, &skill_name, offline).await?;
            findings.extend(skill_findings);
            skills_scanned += 1;
        }
    }

    // Sort findings by severity (highest first)
    findings.sort_by(|a, b| b.severity.cmp(&a.severity));

    let hash_baseline_updated = update_hash_baseline(&path, &findings).await?;

    Ok(AuditReport {
        skills_scanned,
        findings,
        hash_baseline_updated,
    })
}

/// Check a single skill (by path or clawhub ID)
pub async fn check_skill(skill: &str, offline: bool) -> Result<AuditReport> {
    let local_path = resolve_home(skill);
    let path = if local_path.exists() || !is_probably_clawhub_id(skill) {
        local_path
    } else {
        if offline {
            anyhow::bail!(
                "--offline mode: cannot fetch ClawHub skill '{}'; provide a local path instead",
                skill
            );
        }

        // Looks like a ClawHub ID (author/skill-name) — fetch it to a temp dir
        fetch_clawhub_skill(skill).await?
    };

    let skill_name = path
        .file_name()
        .unwrap_or_default()
        .to_string_lossy()
        .to_string();

    let findings = audit_skill_dir(&path, &skill_name, offline).await?;
    let mut sorted = findings;
    sorted.sort_by(|a, b| b.severity.cmp(&a.severity));

    Ok(AuditReport {
        skills_scanned: 1,
        findings: sorted,
        hash_baseline_updated: false,
    })
}

/// Move a skill to the quarantine directory
pub async fn isolate_skill(skill_name: &str) -> Result<()> {
    let skills_dir = resolve_home("~/.openclaw/skills");
    let quarantine_dir = resolve_home("~/.sentinel/quarantine");
    fs::create_dir_all(&quarantine_dir).await?;

    let skill_path = skills_dir.join(skill_name);
    if !skill_path.exists() {
        anyhow::bail!(
            "Skill '{}' not found in {}",
            skill_name,
            skills_dir.display()
        );
    }

    let dest = quarantine_dir.join(skill_name);
    fs::rename(&skill_path, &dest).await?;
    info!(
        "Skill '{}' moved to quarantine: {}",
        skill_name,
        dest.display()
    );
    Ok(())
}

/// Submit a skill report to ClawHub
pub async fn report_skill(skill_name: &str) -> Result<()> {
    let client = reqwest::Client::new();
    let resp = client
        .post("https://clawhub.ai/api/v1/report")
        .json(&serde_json::json!({ "skill": skill_name, "reporter": "runtime-sentinel" }))
        .send()
        .await?;

    if !resp.status().is_success() {
        anyhow::bail!("ClawHub report API returned {}", resp.status());
    }
    Ok(())
}

// ─── Internal helpers ────────────────────────────────────────────────────────

async fn audit_skill_dir(path: &Path, skill_name: &str, offline: bool) -> Result<Vec<Finding>> {
    let mut findings = Vec::new();

    // 1. Hash integrity check
    findings.extend(check_hashes(path, skill_name).await?);

    // 2. Credential exposure scan
    findings.extend(scan_credentials(path, skill_name).await?);

    // 3. Prompt injection patterns in SKILL.md (meta-check: does the skill
    //    itself contain injection patterns targeting the agent loading it?)
    let skill_md = path.join("SKILL.md");
    if skill_md.exists() {
        let content = fs::read_to_string(&skill_md).await?;
        let inj = injection::scan_text(&content, skill_name);
        findings.extend(inj);

        // 4. Permission declaration audit
        findings.extend(audit_permissions(&content, path, skill_name).await?);
    }

    // 5. VirusTotal hash lookup (online only)
    if !offline {
        findings.extend(virustotal_check(path, skill_name).await?);
    }

    Ok(findings)
}

async fn check_hashes(path: &Path, skill_name: &str) -> Result<Vec<Finding>> {
    let baseline_path = resolve_home("~/.sentinel/baselines").join(format!("{}.json", skill_name));
    let mut findings = Vec::new();

    let current_hashes = compute_dir_hashes(path).await?;

    if baseline_path.exists() {
        let stored: HashMap<String, String> =
            serde_json::from_str(&fs::read_to_string(&baseline_path).await?)?;

        for (file, hash) in &current_hashes {
            match stored.get(file) {
                None => {
                    findings.push(Finding {
                        skill: skill_name.to_string(),
                        severity: Severity::Medium,
                        category: FindingCategory::HashMismatch,
                        detail: format!("New file appeared post-install: {}", file),
                        file: Some(file.clone()),
                        line: None,
                    });
                }
                Some(stored_hash) if stored_hash != hash => {
                    let severity = if file.ends_with(".sh")
                        || file.ends_with(".py")
                        || file.ends_with(".js")
                        || file == "SKILL.md"
                    {
                        Severity::High
                    } else {
                        Severity::Medium
                    };
                    findings.push(Finding {
                        skill: skill_name.to_string(),
                        severity,
                        category: FindingCategory::HashMismatch,
                        detail: format!("File modified since install: {}", file),
                        file: Some(file.clone()),
                        line: None,
                    });
                }
                _ => {}
            }
        }
    } else {
        // No baseline yet — write one now
        let baseline_dir = resolve_home("~/.sentinel/baselines");
        fs::create_dir_all(&baseline_dir).await?;
        let json = serde_json::to_string_pretty(&current_hashes)?;
        fs::write(&baseline_path, json).await?;
        info!("Baseline recorded for skill '{}'", skill_name);
    }

    Ok(findings)
}

async fn compute_dir_hashes(path: &Path) -> Result<HashMap<String, String>> {
    let mut hashes = HashMap::new();
    let mut stack = vec![path.to_path_buf()];

    while let Some(dir) = stack.pop() {
        let mut entries = fs::read_dir(&dir).await?;
        while let Some(entry) = entries.next_entry().await? {
            let p = entry.path();
            if p.is_dir() {
                stack.push(p);
            } else {
                let content = fs::read(&p).await?;
                let hash = hex::encode(Sha256::digest(&content));
                let rel = p
                    .strip_prefix(path)
                    .unwrap_or(&p)
                    .to_string_lossy()
                    .to_string();
                hashes.insert(rel, hash);
            }
        }
    }
    Ok(hashes)
}

async fn scan_credentials(path: &Path, skill_name: &str) -> Result<Vec<Finding>> {
    let mut findings = Vec::new();
    let mut stack = vec![path.to_path_buf()];

    while let Some(dir) = stack.pop() {
        let mut entries = fs::read_dir(&dir).await?;
        while let Some(entry) = entries.next_entry().await? {
            let p = entry.path();
            if p.is_dir() {
                stack.push(p);
                continue;
            }
            // Only scan text-like files
            if let Ok(content) = fs::read_to_string(&p).await {
                let rel = p
                    .strip_prefix(path)
                    .unwrap_or(&p)
                    .to_string_lossy()
                    .to_string();

                for (i, line) in content.lines().enumerate() {
                    for (pattern_name, re) in CREDENTIAL_PATTERNS.iter() {
                        if re.is_match(line) {
                            findings.push(Finding {
                                skill: skill_name.to_string(),
                                severity: Severity::High,
                                category: FindingCategory::CredentialExposure,
                                detail: format!("Possible {} exposed in plaintext", pattern_name),
                                file: Some(rel.clone()),
                                line: Some(i + 1),
                            });
                        }
                    }

                    // High-entropy string check (likely a key/secret)
                    for token in line.split_whitespace() {
                        if token.len() >= 32 && looks_like_secret(token) {
                            findings.push(Finding {
                                skill: skill_name.to_string(),
                                severity: Severity::Medium,
                                category: FindingCategory::CredentialExposure,
                                detail: format!("High-entropy token (possible secret) in {}", rel),
                                file: Some(rel.clone()),
                                line: Some(i + 1),
                            });
                        }
                    }
                }
            }
        }
    }
    Ok(findings)
}

/// Rough heuristic: high Shannon entropy + alphanumeric/base64 characters
fn looks_like_secret(s: &str) -> bool {
    let charset_ok = s
        .chars()
        .all(|c| c.is_alphanumeric() || "+/=_-".contains(c));
    if !charset_ok {
        return false;
    }
    let ent = entropy::metric_entropy(s);
    ent > 4.5 // bits per character threshold
}

async fn audit_permissions(
    skill_md_content: &str,
    skill_path: &Path,
    skill_name: &str,
) -> Result<Vec<Finding>> {
    let mut findings = Vec::new();

    // Check if skill has shell scripts but doesn't declare `binaries`
    let has_scripts = {
        let mut found = false;
        let mut stack = vec![skill_path.to_path_buf()];
        'outer: while let Some(dir) = stack.pop() {
            if let Ok(mut entries) = fs::read_dir(&dir).await {
                while let Some(Ok(entry)) = entries.next_entry().await.ok() {
                    let p = entry.path();
                    if p.is_dir() {
                        stack.push(p);
                    } else if matches!(
                        p.extension().and_then(|e| e.to_str()),
                        Some("sh") | Some("py") | Some("js") | Some("rb")
                    ) {
                        found = true;
                        break 'outer;
                    }
                }
            }
        }
        found
    };

    let declares_binaries = skill_md_content.contains("binaries:");

    if has_scripts && !declares_binaries {
        findings.push(Finding {
            skill: skill_name.to_string(),
            severity: Severity::Medium,
            category: FindingCategory::UndeclaredPermission,
            detail: "Skill contains executable scripts but does not declare `binaries` in SKILL.md frontmatter".to_string(),
            file: Some("SKILL.md".to_string()),
            line: None,
        });
    }

    Ok(findings)
}

async fn virustotal_check(path: &Path, skill_name: &str) -> Result<Vec<Finding>> {
    // Hash all files and submit to VirusTotal's public hash lookup
    // (no file upload — hash-only lookup preserves privacy)
    let hashes = compute_dir_hashes(path).await?;
    let client = reqwest::Client::new();
    let mut findings = Vec::new();

    for (file, hash) in &hashes {
        let url = format!("https://www.virustotal.com/api/v3/files/{}", hash);
        if let Ok(resp) = client.get(&url).send().await {
            if resp.status() == 200 {
                if let Ok(body) = resp.json::<serde_json::Value>().await {
                    let malicious = body["data"]["attributes"]["last_analysis_stats"]["malicious"]
                        .as_u64()
                        .unwrap_or(0);
                    if malicious > 0 {
                        findings.push(Finding {
                            skill: skill_name.to_string(),
                            severity: Severity::Critical,
                            category: FindingCategory::SuspiciousContent,
                            detail: format!(
                                "VirusTotal: {} engine(s) flagged {} as malicious",
                                malicious, file
                            ),
                            file: Some(file.clone()),
                            line: None,
                        });
                    }
                }
            }
        }
    }
    Ok(findings)
}

fn is_probably_clawhub_id(skill: &str) -> bool {
    if skill.starts_with('.') || skill.starts_with('/') || skill.starts_with('~') {
        return false;
    }

    let mut parts = skill.split('/');
    let author = parts.next();
    let name = parts.next();

    // Exactly two path segments in the form `author/skill-name`
    author.is_some() && name.is_some() && parts.next().is_none()
}

async fn fetch_clawhub_skill(clawhub_id: &str) -> Result<PathBuf> {
    // Download skill zip to a temp directory for scanning before install
    let client = reqwest::Client::new();
    let url = format!("https://clawhub.ai/api/v1/skills/{}/download", clawhub_id);
    let resp = client.get(&url).send().await?;
    if !resp.status().is_success() {
        anyhow::bail!(
            "Could not fetch skill '{}' from ClawHub: {}",
            clawhub_id,
            resp.status()
        );
    }
    let bytes = resp.bytes().await?;
    let tmp = tempfile::tempdir()?;
    let zip_path = tmp.path().join("skill.zip");
    tokio::fs::write(&zip_path, &bytes).await?;

    // Extract (basic zip extraction — production would use zip crate)
    let output = tokio::process::Command::new("unzip")
        .arg("-q")
        .arg(&zip_path)
        .arg("-d")
        .arg(tmp.path())
        .output()
        .await?;

    if !output.status.success() {
        anyhow::bail!("Failed to extract skill archive");
    }

    // Return path to extracted skill directory
    let skill_name = clawhub_id.split('/').last().unwrap_or(clawhub_id);
    Ok(tmp.into_path().join(skill_name))
}

async fn update_hash_baseline(_skills_path: &Path, findings: &[Finding]) -> Result<bool> {
    // If no hash mismatches, baseline is current
    let has_mismatch = findings
        .iter()
        .any(|f| matches!(f.category, FindingCategory::HashMismatch));
    Ok(!has_mismatch)
}

fn resolve_home(path: &str) -> PathBuf {
    if let Some(stripped) = path.strip_prefix("~/") {
        dirs::home_dir()
            .unwrap_or_else(|| PathBuf::from("/tmp"))
            .join(stripped)
    } else {
        PathBuf::from(path)
    }
}

#[cfg(test)]
mod tests {
    use super::is_probably_clawhub_id;

    #[test]
    fn clawhub_id_detection_accepts_author_skill_name() {
        assert!(is_probably_clawhub_id("author/skill-name"));
    }

    #[test]
    fn clawhub_id_detection_rejects_local_paths() {
        assert!(!is_probably_clawhub_id("./author/skill-name"));
        assert!(!is_probably_clawhub_id("/tmp/skill"));
        assert!(!is_probably_clawhub_id("~/skills/skill-a"));
    }

    #[test]
    fn clawhub_id_detection_rejects_non_canonical_ids() {
        assert!(!is_probably_clawhub_id("author"));
        assert!(!is_probably_clawhub_id("author/skill-name/extra"));
    }
}

use anyhow::Result;
use notify::{Config, Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::mpsc;
use tokio::fs;
use tracing::{error, info, warn};

use crate::audit;
use crate::egress;
use crate::payment;
use crate::process;
use chrono::{DateTime, Utc};

const DAEMON_PID_FILE: &str = "~/.sentinel/daemon.pid";
const DAEMON_LOG_FILE: &str = "~/.sentinel/daemon.log";

#[derive(Debug, Serialize, Deserialize)]
struct DaemonState {
    pid: u32,
    started_at: String,
    premium_until: Option<String>,
}

pub async fn start(offline: bool) -> Result<()> {
    let pid_path = resolve_home(DAEMON_PID_FILE);

    if pid_path.exists() {
        let state: DaemonState = serde_json::from_str(&fs::read_to_string(&pid_path).await?)?;
        if process_running(state.pid) {
            println!(
                "Daemon already running (PID {}). Use `sentinel daemon stop` first.",
                state.pid
            );
            return Ok(());
        }

        warn!(
            "Removing stale daemon PID file for non-running PID {}",
            state.pid
        );
        fs::remove_file(&pid_path).await?;
    }

    // Premium gate: acquire x402 session token unless offline
    let mut premium_until = None;
    if !offline {
        println!("Acquiring premium session via x402...");
        match payment::execute_x402_payment(
            "https://api.runtime-sentinel.dev/v1/daemon/start",
            &serde_json::json!({"features": ["egress", "process_anomaly", "file_watch"]}),
        )
        .await
        {
            Ok(resp) => {
                premium_until = extract_premium_expiry(&resp);
                info!("Premium session granted: {:?}", resp);
            }
            Err(e) => {
                warn!(
                    "Premium payment failed ({}). Starting in free-tier mode (file watch only).",
                    e
                );
            }
        }
    }

    let state = DaemonState {
        pid: std::process::id(),
        started_at: chrono::Utc::now().to_rfc3339(),
        premium_until,
    };
    fs::create_dir_all(resolve_home("~/.sentinel")).await?;
    fs::write(&pid_path, serde_json::to_string(&state)?).await?;

    println!("✅ Daemon started (PID {})", state.pid);
    println!("Watching: ~/.openclaw/skills, SOUL.md, MEMORY.md");
    println!("Log: {}", DAEMON_LOG_FILE);

    run_watch_loop().await
}

pub async fn stop() -> Result<()> {
    let pid_path = resolve_home(DAEMON_PID_FILE);
    if !pid_path.exists() {
        println!("Daemon is not running.");
        return Ok(());
    }
    let state: DaemonState = serde_json::from_str(&fs::read_to_string(&pid_path).await?)?;
    if !process_running(state.pid) {
        fs::remove_file(&pid_path).await?;
        println!(
            "Daemon PID file existed, but process {} is not running. Cleaned up stale state.",
            state.pid
        );
        return Ok(());
    }

    // Send SIGTERM to the daemon process
    #[cfg(unix)]
    unsafe {
        libc::kill(state.pid as i32, libc::SIGTERM);
    }

    fs::remove_file(&pid_path).await?;
    println!("Daemon stopped (was PID {}).", state.pid);
    Ok(())
}

pub async fn status() -> Result<()> {
    let pid_path = resolve_home(DAEMON_PID_FILE);
    if !pid_path.exists() {
        println!("Daemon: not running");
        return Ok(());
    }
    let state: DaemonState = serde_json::from_str(&fs::read_to_string(&pid_path).await?)?;
    if !process_running(state.pid) {
        fs::remove_file(&pid_path).await?;
        println!(
            "Daemon: not running (cleaned up stale PID file for {})",
            state.pid
        );
        return Ok(());
    }

    println!("Daemon: running (PID {})", state.pid);
    println!("Started: {}", state.started_at);
    if let Some(premium_until) = active_premium_until(&state) {
        println!("Mode: paid");
        println!("Premium active until: {}", premium_until);
    } else {
        println!("Mode: free tier (file watch only)");
    }
    Ok(())
}

fn extract_premium_expiry(resp: &serde_json::Value) -> Option<String> {
    let metadata = resp.get("metadata").unwrap_or(resp);
    let keys = [
        "premium_until",
        "expires_at",
        "expiresAt",
        "expiry",
        "valid_until",
        "validUntil",
    ];

    keys.into_iter().find_map(|key| {
        metadata.get(key).and_then(|value| {
            value.as_str().and_then(normalize_timestamp).or_else(|| {
                value
                    .as_i64()
                    .and_then(|secs| DateTime::from_timestamp(secs, 0).map(|dt| dt.to_rfc3339()))
            })
        })
    })
}

fn normalize_timestamp(raw: &str) -> Option<String> {
    if let Ok(dt) = DateTime::parse_from_rfc3339(raw) {
        return Some(dt.with_timezone(&Utc).to_rfc3339());
    }

    if let Ok(secs) = raw.parse::<i64>() {
        return DateTime::from_timestamp(secs, 0).map(|dt| dt.to_rfc3339());
    }

    None
}

fn active_premium_until(state: &DaemonState) -> Option<&str> {
    let premium_until = state.premium_until.as_deref()?;
    let parsed = DateTime::parse_from_rfc3339(premium_until).ok()?;
    (parsed.with_timezone(&Utc) > Utc::now()).then_some(premium_until)
}

pub async fn logs(lines: usize) -> Result<()> {
    let log_path = resolve_home(DAEMON_LOG_FILE);
    if !log_path.exists() {
        println!("No log file found at {}", DAEMON_LOG_FILE);
        return Ok(());
    }
    let content = fs::read_to_string(&log_path).await?;
    let all_lines: Vec<&str> = content.lines().collect();
    let start = all_lines.len().saturating_sub(lines);
    for line in &all_lines[start..] {
        println!("{}", line);
    }
    Ok(())
}

async fn run_watch_loop() -> Result<()> {
    let (tx, rx) = mpsc::channel::<notify::Result<Event>>();

    let mut watcher = RecommendedWatcher::new(tx, Config::default())?;

    let skills_dir = resolve_home("~/.openclaw/skills");
    let soul_md = resolve_home("~/.openclaw/SOUL.md");
    let memory_md = resolve_home("~/.openclaw/MEMORY.md");

    if skills_dir.exists() {
        watcher.watch(&skills_dir, RecursiveMode::Recursive)?;
    }
    if soul_md.exists() {
        watcher.watch(&soul_md, RecursiveMode::NonRecursive)?;
    }
    if memory_md.exists() {
        watcher.watch(&memory_md, RecursiveMode::NonRecursive)?;
    }

    info!("File watcher active");

    let egress_interval = std::time::Duration::from_secs(10);
    let mut last_egress_scan = std::time::Instant::now() - egress_interval;

    loop {
        match rx.recv_timeout(std::time::Duration::from_secs(2)) {
            Ok(Ok(event)) => handle_fs_event(event).await,
            Ok(Err(e)) => error!("Watcher error: {:?}", e),
            Err(mpsc::RecvTimeoutError::Timeout) => {}
            Err(mpsc::RecvTimeoutError::Disconnected) => break,
        }

        if last_egress_scan.elapsed() >= egress_interval {
            if let Err(e) = scan_egress().await {
                warn!("Egress scan failed: {}", e);
            }
            if let Err(e) = scan_process_anomalies().await {
                warn!("Process anomaly scan failed: {}", e);
            }
            last_egress_scan = std::time::Instant::now();
        }
    }

    Ok(())
}

async fn scan_egress() -> Result<()> {
    let skill_pids = process::collect_skill_roots().await?;
    if skill_pids.is_empty() {
        return Ok(());
    }

    let events = egress::snapshot_connections(&skill_pids).await?;
    for event in events.into_iter().filter(|e| !e.declared) {
        let skill = event
            .skill_name
            .clone()
            .unwrap_or_else(|| event.process_name.clone());
        let severity = egress::undeclared_severity(&event.remote_addr, event.remote_port);
        let msg = format!(
            "[{}] {}: Undeclared outbound connection from pid {} ({}) to {}:{}",
            severity, skill, event.pid, event.process_name, event.remote_addr, event.remote_port
        );

        log_alert(&msg).await;
        if severity >= crate::audit::Severity::High {
            eprintln!("🔴 {}", msg);
        } else {
            eprintln!("🟠 {}", msg);
        }
    }

    Ok(())
}

async fn scan_process_anomalies() -> Result<()> {
    let findings = process::snapshot_skill_process_findings().await?;
    for finding in findings {
        let msg = format!(
            "[{}] {}: Undeclared process execution pid {} (ppid {}) binary={} command={}",
            finding.severity,
            finding.skill_name,
            finding.pid,
            finding.ppid,
            finding.observed_binary,
            finding.command
        );

        log_alert(&msg).await;
        if finding.severity >= crate::audit::Severity::High {
            eprintln!("🔴 {}", msg);
        } else {
            eprintln!("🟠 {}", msg);
        }
    }

    Ok(())
}

async fn handle_fs_event(event: Event) {
    match event.kind {
        EventKind::Modify(_) | EventKind::Create(_) => {
            for path in &event.paths {
                let path_str = path.to_string_lossy();

                // SOUL.md / MEMORY.md writes are always CRITICAL
                if path_str.ends_with("SOUL.md") || path_str.ends_with("MEMORY.md") {
                    let msg = format!(
                        "CRITICAL: Unauthorized write to {} detected. Possible skill poisoning.",
                        path_str
                    );
                    log_alert(&msg).await;
                    eprintln!("🚨 {}", msg);
                    continue;
                }

                // Skill file modifications
                if path_str.contains("/.openclaw/skills/") {
                    // Re-audit the affected skill
                    if let Some(skill_dir) = find_skill_root(path) {
                        let skill_name = skill_dir
                            .file_name()
                            .unwrap_or_default()
                            .to_string_lossy()
                            .to_string();
                        info!("Re-auditing skill '{}' due to file change", skill_name);
                        match audit::run_audit(&skill_dir.to_string_lossy(), false).await {
                            Ok(report) => {
                                for finding in report.findings {
                                    let msg = format!(
                                        "[{}] {}: {}",
                                        finding.severity, finding.skill, finding.detail
                                    );
                                    log_alert(&msg).await;
                                    if finding.severity >= crate::audit::Severity::High {
                                        eprintln!("🔴 {}", msg);
                                    }
                                }
                            }
                            Err(e) => error!("Re-audit failed: {}", e),
                        }
                    }
                }
            }
        }
        _ => {}
    }
}

fn find_skill_root(path: &std::path::Path) -> Option<PathBuf> {
    // Walk up until we find the skills directory's direct child
    let mut current = path.to_path_buf();
    while let Some(parent) = current.parent() {
        if parent.ends_with(".openclaw/skills") {
            return Some(current);
        }
        current = parent.to_path_buf();
    }
    None
}

async fn log_alert(msg: &str) {
    let log_path = resolve_home(DAEMON_LOG_FILE);
    let entry = format!("[{}] {}\n", chrono::Utc::now().to_rfc3339(), msg);
    if let Ok(mut file) = tokio::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path)
        .await
    {
        use tokio::io::AsyncWriteExt;
        let _ = file.write_all(entry.as_bytes()).await;
    }
}

fn resolve_home(path: &str) -> PathBuf {
    if let Some(stripped) = path.strip_prefix("~/") {
        dirs::home_dir()
            .unwrap_or_else(|| PathBuf::from("/tmp"))
            .join(stripped)
    } else {
        PathBuf::from(path)
    }
}

fn process_running(pid: u32) -> bool {
    #[cfg(unix)]
    unsafe {
        if libc::kill(pid as i32, 0) == 0 {
            return true;
        }

        return std::io::Error::last_os_error().raw_os_error() == Some(libc::EPERM);
    }

    #[cfg(not(unix))]
    {
        let _ = pid;
        true
    }
}

// egress.rs — Network egress monitoring (premium)
// Attributes outbound connections to the skill subprocesses that initiated them.
// Uses /proc/net/tcp on Linux and lsof on macOS.

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::path::PathBuf;
use tokio::fs;
use tracing::{debug, info, warn};

#[derive(Debug, Serialize, Deserialize)]
pub struct EgressEvent {
    pub pid: u32,
    pub process_name: String,
    pub skill_name: Option<String>,
    pub remote_addr: String,
    pub remote_port: u16,
    pub declared: bool, // true if skill declared this connection in its manifest
}

#[derive(Debug, Clone)]
struct SocketEntry {
    remote_addr: String,
    remote_port: u16,
    inode: u64,
}

pub async fn snapshot_connections(skill_pids: &[(u32, String)]) -> Result<Vec<EgressEvent>> {
    info!(
        "Snapshotting network connections for {} skill processes",
        skill_pids.len()
    );

    #[cfg(target_os = "linux")]
    return linux_connections(skill_pids).await;

    #[cfg(target_os = "macos")]
    return macos_connections(skill_pids).await;

    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    anyhow::bail!("Egress monitoring not supported on this platform")
}

#[cfg(target_os = "linux")]
async fn linux_connections(skill_pids: &[(u32, String)]) -> Result<Vec<EgressEvent>> {
    let mut inode_map: HashMap<u64, SocketEntry> = HashMap::new();
    for file in ["/proc/net/tcp", "/proc/net/tcp6"] {
        for socket in parse_proc_net_file(file).await? {
            inode_map.insert(socket.inode, socket);
        }
    }

    let mut events = Vec::new();
    let mut seen = HashSet::new();

    for (pid, skill_name) in skill_pids {
        let declared_destinations = load_declared_destinations(skill_name).await;
        let process_name = read_process_name(*pid)
            .await
            .unwrap_or_else(|| skill_name.clone());

        let fd_dir = format!("/proc/{}/fd", pid);
        let mut dir = match fs::read_dir(&fd_dir).await {
            Ok(dir) => dir,
            Err(e) => {
                debug!("Skipping PID {} fd scan ({}): {}", pid, fd_dir, e);
                continue;
            }
        };

        while let Ok(Some(entry)) = dir.next_entry().await {
            let link_target = match fs::read_link(entry.path()).await {
                Ok(target) => target,
                Err(_) => continue,
            };

            if let Some(inode) = parse_socket_inode(&link_target) {
                if let Some(socket) = inode_map.get(&inode) {
                    let key = (*pid, inode, socket.remote_port);
                    if seen.insert(key) {
                        events.push(EgressEvent {
                            pid: *pid,
                            process_name: process_name.clone(),
                            skill_name: Some(skill_name.clone()),
                            remote_addr: socket.remote_addr.clone(),
                            remote_port: socket.remote_port,
                            declared: destination_declared(
                                &declared_destinations,
                                &socket.remote_addr,
                            ),
                        });
                    }
                }
            }
        }
    }

    Ok(events)
}

#[cfg(target_os = "linux")]
async fn parse_proc_net_file(path: &str) -> Result<Vec<SocketEntry>> {
    let content = fs::read_to_string(path).await?;
    let mut sockets = Vec::new();

    for line in content.lines().skip(1) {
        let cols: Vec<&str> = line.split_whitespace().collect();
        if cols.len() < 10 {
            continue;
        }

        let state = cols[3];
        if state != "01" && state != "02" {
            continue;
        }

        let inode = match cols[9].parse::<u64>() {
            Ok(inode) => inode,
            Err(_) => continue,
        };

        let Some((remote_addr, remote_port)) = decode_proc_address(cols[2]) else {
            continue;
        };

        if remote_port == 0 {
            continue;
        }

        sockets.push(SocketEntry {
            remote_addr,
            remote_port,
            inode,
        });
    }

    Ok(sockets)
}

#[cfg(target_os = "linux")]
fn decode_proc_address(raw: &str) -> Option<(String, u16)> {
    let (hex_addr, hex_port) = raw.split_once(':')?;
    let port = u16::from_str_radix(hex_port, 16).ok()?;

    if hex_addr.len() == 8 {
        let mut octets = [0u8; 4];
        for i in 0..4 {
            let idx = i * 2;
            octets[3 - i] = u8::from_str_radix(&hex_addr[idx..idx + 2], 16).ok()?;
        }
        return Some((Ipv4Addr::from(octets).to_string(), port));
    }

    if hex_addr.len() == 32 {
        let mut bytes = [0u8; 16];
        for i in 0..16 {
            let idx = i * 2;
            bytes[15 - i] = u8::from_str_radix(&hex_addr[idx..idx + 2], 16).ok()?;
        }
        return Some((Ipv6Addr::from(bytes).to_string(), port));
    }

    None
}

fn parse_socket_inode(link_target: &PathBuf) -> Option<u64> {
    let text = link_target.to_string_lossy();
    let inner = text.strip_prefix("socket:[")?.strip_suffix(']')?;
    inner.parse().ok()
}

async fn read_process_name(pid: u32) -> Option<String> {
    let comm_path = format!("/proc/{}/comm", pid);
    fs::read_to_string(comm_path)
        .await
        .ok()
        .map(|s| s.trim().to_string())
}

async fn load_declared_destinations(skill_name: &str) -> Vec<String> {
    if skill_name.is_empty() {
        return Vec::new();
    }

    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/tmp"));
    let skill_md = home
        .join(".openclaw/skills")
        .join(skill_name)
        .join("SKILL.md");
    let content = match fs::read_to_string(skill_md).await {
        Ok(content) => content.to_lowercase(),
        Err(_) => return Vec::new(),
    };

    let mut out = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("-") {
            out.push(trimmed.trim_start_matches('-').trim().to_string());
        }
        if trimmed.starts_with("network:") || trimmed.starts_with("domains:") {
            if let Some((_, rest)) = trimmed.split_once(':') {
                out.push(rest.trim().to_string());
            }
        }
    }
    out
}

fn destination_declared(declared: &[String], remote_addr: &str) -> bool {
    if declared.is_empty() {
        return false;
    }

    let remote_addr = remote_addr.to_lowercase();
    declared.iter().any(|entry| {
        let entry = entry.trim();
        entry == "any"
            || entry == "*"
            || entry.contains(&remote_addr)
            || entry
                .strip_prefix("*.")
                .map(|suffix| remote_addr.ends_with(suffix))
                .unwrap_or(false)
    })
}

#[cfg(target_os = "macos")]
async fn macos_connections(skill_pids: &[(u32, String)]) -> Result<Vec<EgressEvent>> {
    if skill_pids.is_empty() {
        return Ok(Vec::new());
    }

    let mut skill_name_by_pid = HashMap::new();
    for (pid, skill_name) in skill_pids {
        skill_name_by_pid.insert(*pid, skill_name.clone());
    }

    let pids: Vec<String> = skill_pids.iter().map(|(pid, _)| pid.to_string()).collect();
    let output = tokio::process::Command::new("lsof")
        .args(["-i", "-n", "-P", "-p", &pids.join(",")])
        .output()
        .await?;

    if !output.status.success() {
        warn!("lsof returned non-zero status: {}", output.status);
        return Ok(Vec::new());
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let mut events = Vec::new();
    let mut seen = HashSet::new();

    for line in text.lines().skip(1) {
        let cols: Vec<&str> = line.split_whitespace().collect();
        if cols.len() < 9 {
            continue;
        }

        let Ok(pid) = cols[1].parse::<u32>() else {
            continue;
        };

        if !skill_name_by_pid.contains_key(&pid) {
            continue;
        }

        if !(line.contains("->") || line.contains("TCP")) {
            continue;
        }

        let Some(name_col) = cols.last() else {
            continue;
        };

        let Some((remote_addr, remote_port)) = parse_lsof_destination(name_col) else {
            continue;
        };

        let key = (pid, remote_addr.clone(), remote_port);
        if !seen.insert(key) {
            continue;
        }

        let skill_name = skill_name_by_pid.get(&pid).cloned();
        let declared_destinations = if let Some(skill) = &skill_name {
            load_declared_destinations(skill).await
        } else {
            Vec::new()
        };

        events.push(EgressEvent {
            pid,
            process_name: cols[0].to_string(),
            skill_name,
            remote_addr: remote_addr.clone(),
            remote_port,
            declared: destination_declared(&declared_destinations, &remote_addr),
        });
    }

    Ok(events)
}

#[cfg(target_os = "macos")]
fn parse_lsof_destination(raw: &str) -> Option<(String, u16)> {
    let endpoint = raw.split("->").last()?.trim();
    let (addr, port_str) = endpoint.rsplit_once(':')?;
    let port = port_str.parse::<u16>().ok()?;
    Some((addr.trim_matches(&['[', ']'][..]).to_string(), port))
}

pub fn undeclared_severity(remote_addr: &str, remote_port: u16) -> crate::audit::Severity {
    if remote_port == 4444 || remote_port == 31337 || remote_port == 6667 {
        return crate::audit::Severity::Critical;
    }

    let ip = remote_addr.parse::<IpAddr>().ok();
    if is_internal_destination(ip) {
        crate::audit::Severity::Medium
    } else {
        crate::audit::Severity::High
    }
}

fn is_internal_destination(ip: Option<IpAddr>) -> bool {
    match ip {
        Some(IpAddr::V4(v4)) => {
            v4.is_loopback() || v4.is_private() || v4.is_link_local() || v4.is_multicast()
        }
        Some(IpAddr::V6(v6)) => {
            v6.is_loopback()
                || v6.is_unique_local()
                || v6.is_unicast_link_local()
                || v6.is_multicast()
        }
        None => false,
    }
}

use crate::audit::{Finding, FindingCategory, Severity};
use crate::patterns::INJECTION_PATTERNS;
use tracing::debug;

/// Scan arbitrary text for prompt injection patterns.
/// Used both for scanning skill SKILL.md files and for scanning
/// external data (emails, web pages, etc.) before they enter the agent context.
pub fn scan_text(content: &str, source_label: &str) -> Vec<Finding> {
    let mut findings = Vec::new();

    for line in content.lines().enumerate().map(|(i, l)| (i + 1, l)) {
        let (line_num, text) = line;
        let text_lower = text.to_lowercase();

        for (pattern_name, re, severity) in INJECTION_PATTERNS.iter() {
            if re.is_match(&text_lower) {
                debug!(
                    "Injection pattern '{}' matched at line {}",
                    pattern_name, line_num
                );
                findings.push(Finding {
                    skill: source_label.to_string(),
                    severity: *severity,
                    category: FindingCategory::InjectionPattern,
                    detail: format!("Prompt injection pattern '{}' detected", pattern_name),
                    file: None,
                    line: Some(line_num),
                });
            }
        }

        // Unicode homoglyph detection — look for non-ASCII characters that
        // visually resemble ASCII instruction keywords
        if contains_homoglyphs(text) {
            findings.push(Finding {
                skill: source_label.to_string(),
                severity: Severity::High,
                category: FindingCategory::InjectionPattern,
                detail: "Unicode homoglyph substitution detected (possible evasion attempt)"
                    .to_string(),
                file: None,
                line: Some(line_num),
            });
        }

        // Base64 payload detection — look for large base64 blobs that could
        // contain encoded instructions
        if let Some(decoded) = find_and_decode_base64(text) {
            if looks_like_instructions(&decoded) {
                findings.push(Finding {
                    skill: source_label.to_string(),
                    severity: Severity::High,
                    category: FindingCategory::InjectionPattern,
                    detail: "Base64-encoded content decodes to instruction-like text".to_string(),
                    file: None,
                    line: Some(line_num),
                });
            }
        }
    }

    findings
}

/// Scan external data (email body, web page content, API response, etc.)
/// before it enters the agent's reasoning context.
/// Returns (safe_to_use, findings)
pub fn scan_external_data(data: &str, source: &str) -> (bool, Vec<Finding>) {
    let findings = scan_text(data, source);

    // Block if any HIGH or CRITICAL findings
    let should_block = findings.iter().any(|f| f.severity >= Severity::High);

    (!should_block, findings)
}

fn contains_homoglyphs(text: &str) -> bool {
    // Check for known homoglyphs of common ASCII letters used in injections
    // Focus on visually similar characters in Unicode ranges
    let suspicious_ranges = [
        '\u{0400}'..='\u{04FF}', // Cyrillic
        '\u{0370}'..='\u{03FF}', // Greek
    ];

    let ascii_lookalikes: &[char] = &[
        'а', 'е', 'о', 'р', 'с', 'х', // Cyrillic lookalikes
        'α', 'ε', 'ο', 'ρ', // Greek lookalikes
    ];

    text.chars().any(|c| ascii_lookalikes.contains(&c))
        || text
            .chars()
            .any(|c| suspicious_ranges.iter().any(|r| r.contains(&c)))
}

fn find_and_decode_base64(text: &str) -> Option<String> {
    use base64::{engine::general_purpose::STANDARD, Engine as _};

    // Look for base64-like tokens of at least 60 chars
    for token in text.split_whitespace() {
        if token.len() < 60 {
            continue;
        }
        let cleaned =
            token.trim_matches(|c: char| !c.is_alphanumeric() && c != '+' && c != '/' && c != '=');
        if cleaned.len() < 60 {
            continue;
        }
        if let Ok(decoded) = STANDARD.decode(cleaned) {
            if let Ok(s) = String::from_utf8(decoded) {
                return Some(s);
            }
        }
    }
    None
}

fn looks_like_instructions(text: &str) -> bool {
    let instruction_keywords = [
        "ignore previous",
        "forget your",
        "your new task",
        "system:",
        "assistant:",
        "human:",
        "new instruction",
        "disregard",
        "override",
        "jailbreak",
        "do not follow",
    ];
    let lower = text.to_lowercase();
    instruction_keywords.iter().any(|kw| lower.contains(kw))
}

use anyhow::Result;
use clap::{Parser, Subcommand};
use tracing_subscriber::{fmt, EnvFilter};

mod audit;
mod daemon;
mod egress;
mod injection;
mod patterns;
mod payment;
mod process;
mod report;

#[derive(Parser)]
#[command(
    name = "sentinel",
    about = "runtime-sentinel: OpenClaw runtime security guardian",
    version
)]
struct Cli {
    /// Output JSON instead of human-readable text
    #[arg(long, global = true)]
    json: bool,

    /// Run without any network calls (free tier only)
    #[arg(long, global = true)]
    offline: bool,

    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// First-time setup: generate wallet, run baseline audit
    Setup,

    /// Audit all installed OpenClaw skills (free)
    Audit {
        /// Path to skills directory
        #[arg(long, default_value = "~/.openclaw/skills")]
        path: String,
    },

    /// Check a single skill before installing (free)
    Check {
        /// Path to skill directory or ClawHub skill ID (e.g. author/skill-name)
        skill: String,
    },

    /// Isolate a suspicious skill (move out of active directory)
    Isolate {
        /// Skill name to isolate
        skill: String,
    },

    /// Report a malicious skill to ClawHub
    Report {
        /// Skill name to report
        skill: String,
    },

    /// Daemon management (premium)
    Daemon {
        #[command(subcommand)]
        action: DaemonAction,
    },

    /// Wallet management
    Wallet {
        #[command(subcommand)]
        action: WalletAction,
    },
}

#[derive(Subcommand)]
enum DaemonAction {
    /// Start the guardian in the foreground (use shell backgrounding if desired)
    Start,
    /// Stop the daemon
    Stop,
    /// Show daemon status
    Status,
    /// Tail the audit log
    Logs {
        /// Number of lines to show
        #[arg(short = 'n', default_value = "50")]
        lines: usize,
    },
}

#[derive(Subcommand)]
enum WalletAction {
    /// Show wallet address and USDC balance
    Show,
    /// Print QR code and address to fund wallet with USDC on Base
    Fund,
    /// Set per-day auto-approval spending limit
    SetLimit {
        /// Max USDC per day to auto-approve (0 = always prompt)
        amount: f64,
    },
    /// Export BIP-39 mnemonic for backup (handle with care)
    Export,
    /// Restore wallet from BIP-39 mnemonic
    Recover,
    /// Diagnose wallet and payment issues
    Diagnose,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    // Initialise tracing
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    if cli.json {
        fmt().json().with_env_filter(filter).init();
    } else {
        fmt().with_env_filter(filter).init();
    }

    match cli.command {
        Command::Setup => {
            payment::setup_wallet().await?;
            let results = audit::run_audit("~/.openclaw/skills", cli.offline).await?;
            report::print_audit(&results, cli.json);
        }

        Command::Audit { path } => {
            let results = audit::run_audit(&path, cli.offline).await?;
            report::print_audit(&results, cli.json);
        }

        Command::Check { skill } => {
            let result = audit::check_skill(&skill, cli.offline).await?;
            report::print_check(&result, cli.json);
        }

        Command::Isolate { skill } => {
            audit::isolate_skill(&skill).await?;
            println!(
                "Skill '{}' quarantined. Review ~/.sentinel/quarantine/",
                skill
            );
        }

        Command::Report { skill } => {
            if cli.offline {
                anyhow::bail!("--offline mode: cannot report skills without network access");
            }
            audit::report_skill(&skill).await?;
            println!("Report submitted to ClawHub for '{}'", skill);
        }

        Command::Daemon { action } => match action {
            DaemonAction::Start => daemon::start(cli.offline).await?,
            DaemonAction::Stop => daemon::stop().await?,
            DaemonAction::Status => daemon::status().await?,
            DaemonAction::Logs { lines } => daemon::logs(lines).await?,
        },

        Command::Wallet { action } => match action {
            WalletAction::Show => payment::show_wallet().await?,
            WalletAction::Fund => payment::show_fund_qr().await?,
            WalletAction::SetLimit { amount } => payment::set_limit(amount).await?,
            WalletAction::Export => payment::export_mnemonic().await?,
            WalletAction::Recover => payment::recover_wallet().await?,
            WalletAction::Diagnose => payment::diagnose().await?,
        },
    }

    Ok(())
}

