// https://github.com/coinbase/x402

alloy::sol! {
    /// EIP-712 struct for x402 USDC payment authorization
    struct PaymentAuthorization {
        address from;
        address to;
        uint256 value;
        uint256 validAfter;
        uint256 validBefore;
        bytes32 nonce;
    }
}

